"""Bundle repository licence texts for in-app and offline attribution."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
paths = [root / name for name in ['LICENSE', 'NOTICE', 'THIRD-PARTY-NOTICES.md', 'BRAND-NOTICES.md']]
paths += sorted((root / 'LICENSES').glob('*.txt'))
documents = [{'path': str(path.relative_to(root)), 'text': path.read_text()} for path in paths]
(root / 'src/components/license-notices.js').write_text(
    '// Generated by scripts/generate-license-notices.py from repository licence files.\n'
    'export const licenseDocuments=' + json.dumps(documents, ensure_ascii=False) + ';\n'
)
print(f'Bundled {len(documents)} licence and attribution documents')
